import{_ as a,o as e,c as r,ac as t}from"./chunks/framework.B-3EzaJq.js";const u=JSON.parse('{"title":"关于价格、工资改革的初步方案","description":"","frontmatter":{"prev":{"text":"赵紫阳在党的十三届三中全会上的报告","link":"./赵紫阳在党的十三届三中全会上的报告"},"next":{"text":"中共中央关于加强和改进企业思想政治工作的通知","link":"./中共中央关于加强和改进企业思想政治工作的通知"}},"headers":[],"relativePath":"13/3/关于价格、工资改革的初步方案.md","filePath":"13/3/关于价格、工资改革的初步方案.md"}'),l={name:"13/3/关于价格、工资改革的初步方案.md"};function i(o,p,h,n,s,d){return e(),r("div",null,[...p[0]||(p[0]=[t('<h1 id="关于价格、工资改革的初步方案" tabindex="-1">关于价格、工资改革的初步方案 <a class="header-anchor" href="#关于价格、工资改革的初步方案" aria-label="Permalink to &quot;关于价格、工资改革的初步方案&quot;">​</a></h1><p class="subtitle">国务院物价委员会向中央政治局的汇报提纲</p><p><em>（一九八八年八月十二日）</em><br><em>（中央政治局第十次全体会议一九八八年八月十七日原则通过）</em><br><em>（中国共产党第十三届中央委员会第三次全体会议一九八八年九月三十日原则通过）</em><br></p><nav class="table-of-contents"><ul><li><a href="#一、价格、工资改革的必要性">一、价格、工资改革的必要性</a></li><li><a href="#二、改革需要遵循的主要原则">二、改革需要遵循的主要原则</a></li><li><a href="#三、一九八九至一九九三年价格、工资改革的轮廓设想">三、一九八九至一九九三年价格、工资改革的轮廓设想</a><ul><li><a href="#一-关于价格改革。">（一）关于价格改革。</a></li><li><a href="#二-关于工资改革。">（二）关于工资改革。</a></li></ul></li><li><a href="#四、一九八九年价格、工资改革的初步方案">四、一九八九年价格、工资改革的初步方案</a><ul><li><a href="#一-价格改革的方案。">（一）价格改革的方案。</a></li><li><a href="#二-提价利益的分配。">（二）提价利益的分配。</a></li><li><a href="#三-职工工资的安排。">（三）职工工资的安排。</a></li><li><a href="#四-调价对农民收入和支出的影响。">（四）调价对农民收入和支出的影响。</a></li><li><a href="#五-价格、工资改革对基本建设的影响。">（五）价格、工资改革对基本建设的影响。</a></li><li><a href="#六-财政收支平衡情况。">（六）财政收支平衡情况。</a></li></ul></li><li><a href="#五、主要风险和基本对策">五、主要风险和基本对策</a></li><li><a href="#六、必须采取的配套措施">六、必须采取的配套措施</a></li></ul></nav><h2 id="一、价格、工资改革的必要性" tabindex="-1">一、价格、工资改革的必要性 <a class="header-anchor" href="#一、价格、工资改革的必要性" aria-label="Permalink to &quot;一、价格、工资改革的必要性&quot;">​</a></h2><p>  我国的经济体制改革和经济发展，已经把价格改革这个难度很大的课题突出地提到了我们的面前。价格改革这一关非过不可，既绕不过去，也不能再拖。</p><p>  长期存在的不合理价格体系在前十年的改革中虽然有了 一些改进，但还远没有得到根本性改造，价格形成的合理机制尚未建立，在某些方面甚至出现新的价格扭曲，这已成为深化改革和发展经济的严重障碍。</p><p>  ——生产资料价格的“双轨制”曾经起过积极作用，但现在流弊越来越大，在经济生活中造成种种矛盾、磨擦和漏洞，已经成为许多消极腐败现象的一个重要根源。</p><p>  ——近年来我国物价上涨较多，已经引起社会的普遍关注和群众的严重不安，但在理顺价格关系方面又没有取得应有的进展，如果不主动地抓紧进行改革，听任这种状况发展下去，价格改革的难度将越来越大，后果将越来越严重，最终付出的代价会更大。</p><p>  ——从根本上说，发展社会主义商品经济，必须有一个合理的价格体系和价格形成机制。不下决心进行价格改革，就难以合理配置资源，优化产业结构，保持国民经济长期持续发展；就难以把企业推向市场，促进平等竞争，提高经济效益；就难以理顺经济关系，促进市场体系的发展，逐步建立社会主义商品经济新秩序。</p><p>  在价格改革的同时，工资也要进行必要的调整和改革。随着价格改革的进行和物价总水平的提高，要给职工群众以适当补偿。还要看到，在当前的社会分配领域中，一方面平均主义尚未克服，甚至还有某些发展；另一方面，又出现了分配不公的现象，引起人们的不满。脑体收入倒挂的状况还没有扭转，矛盾还相当突出；标准工资以外的收入比重越来越大，收入分配的可控性和透明度降低；少数人收入过高而没有进行适当调节，有的人非法牟取暴利得不到法律制裁。这种状况，也到了非改革不可的时候了。</p><p>  我国经济多年来持续发展，今后的发展潜力还很大；十年来城乡人民生活在改革开放中得到较大的改善，对进一步改革有了一定的承受能力；各级干部在改革的实践中积累了丰富经验，广大群众逐渐增强了对发展商品经济环境的适应性。我们必须充分利用这些有利条件，不失时机地、果断地把价格、工资改革推向前进。</p><h2 id="二、改革需要遵循的主要原则" tabindex="-1">二、改革需要遵循的主要原则 <a class="header-anchor" href="#二、改革需要遵循的主要原则" aria-label="Permalink to &quot;二、改革需要遵循的主要原则&quot;">​</a></h2><p>  价格、工资改革是一项势在必行而又十分艰巨复杂的任务。我们既要坚决推进改革，又要审时度势，趋利避害，精心筹划，稳步前进。经过反复讨论，我们认为，进行价格、工资改革需要遵循以下一些主要原则：</p><p>  ——<strong>正确确定改革目标。</strong> 价格改革的总方向，是少数重要商品和劳务价格由国家管理，绝大多数商品价格放开，由市场调节，有些商品价格逐步接近国际市场价格，以转换价格形成机制，逐步实现“国家调节市场，市场引导企业”的要求。根据各方面的条件和现实的可能，今后五年左右的时间，价格改革的目标，是初步理顺价格关系，即解决对经济发展和市场发育有严重影响、突出不合理的价格问题。真正形成合理的价格体系和较为完善的市场机制，需要更长的时间。但在今后五年内，我们必须逐步向宏观控制下的市场决定价格过渡。</p><p>  工资改革的重点，一是配合价格改革，在防止工资和物价轮番推进的前提下适当增加职工收入，二是贯彻按劳分配原则，解决工资分配中一些突出不合理的问题。</p><p>  ——<strong>妥善选择实施步骤，五年初步理顺价格关系。</strong> 可以设想经过几年准备，一步到位，以缩短震荡时间，但这样做，震动太大，很可能承受不了，出了问题又难以控制。较为可行的是通盘计划，分步实施。这样做，虽然物价指数要连续几年处于较高水平，也容易造成企业和居民的预期价格上涨心理，但调控的难度小一些，取得成功的把握大一些。</p><p>  ——<strong>坚持边治理通货膨胀边推进改革。</strong> 不改变社会总需求过多地超过总供给的状况，不抑制通货膨胀加剧的势头，价格改革的风险太大，也难以取得成功。在改革的进程中，应当保持生产的适度增长，控制建设总规模和消费基金的过快增长，控制货币的供应量并大力调整信贷结构，把通货膨胀率限制在社会所能承受的范围内，力争经过几年的努力，压缩到两位数以下。</p><p>  ——<strong>合理调节利益分配。</strong> 为了保证价格、工资改革这个大局，在改革中要兼顾各个方面的利益，但各方面也都要作必要的让步，分担改革的负担和风险。对于企业来说，改革应当鼓励先进，鞭策或淘汰落后，而不能保护落后。要妥善处理中央与地方的关系。价格关系的调整和涨价利益的分配，必须有利于实现国家的产业政策，促进产业结构的合理化。</p><p>  ——<strong>实行综合配套改革。</strong> 价格、工资改革涉及经济体制的全局，不能就物价论物价。价格、工资改革不可能也不应当孤军深入，而必须同时搞好各方面的配套改革，并采取正确的财政、税收、金融和外贸外汇政策。最重要的是，要在转换企业机制、加强市场的组织与建设和改进宏观调控机制上取得进展，显著提高企业经济效益和整个经济运行效率。</p><p>  ——<strong>健全立法，严肃执法。</strong> 所有重要改革措施，都必须通过法令和法规的形式确定下来，使之有章可循，坚决改变有法不依、执法不严的状况。这是取得改革成功的重要保障。</p><h2 id="三、一九八九至一九九三年价格、工资改革的轮廓设想" tabindex="-1">三、一九八九至一九九三年价格、工资改革的轮廓设想 <a class="header-anchor" href="#三、一九八九至一九九三年价格、工资改革的轮廓设想" aria-label="Permalink to &quot;三、一九八九至一九九三年价格、工资改革的轮廓设想&quot;">​</a></h2><h3 id="一-关于价格改革。" tabindex="-1">（一）关于价格改革。 <a class="header-anchor" href="#一-关于价格改革。" aria-label="Permalink to &quot;（一）关于价格改革。&quot;">​</a></h3><p>  从一九八九年起，用五年左右时间，初步理顺价格关系，着重解决以下四个方面的问题。</p><p>  1. 逐步放开原材料和加工产品的价格，基本上取消双轨制，在价格形成中强化市场机制的作用。逐步放开价格的商品包括：黑色和有色金属、建筑材料、绝大部分化工原料，以及机械电子产品的价格。放开的步骤和方法，要根据商品的重要性和供求状况区别对待，有的一步放开，有的先调后放，少数特别紧缺的重要品种，在一定时期内还可以实行指定供货，保量不保价，有的要实行专营。在价格放开的过程中，逐步形成国家对市场价格新的调控机制和管理办法。</p><p>  2. 通过有计划地调价，较大幅度地提高能源、交通、通信、公用事业等基础设施的价格，以促进这些基础产业的发展，为国民经济增强后劲。初步设想，五年内主要产品的提价幅度是：</p><p>  国家定价原油，从每吨一百一十三元提高到二百五十到三百五十元；天然气，从每千立方米一百一十七元提高到三百元。原油提价后，成品油和其它石化产品的价格也要适当提高。汽油，从每吨五百八十元提高到七百元。汽油与原油的比价，从五比一调整到二比一（国际市场为一点三五比一）。</p><p>  国家统配煤炭，每吨出厂价从三十五元三角提高到六十到七十元。提价后，统配煤矿可以由现在全行业亏损转变为有适当盈利，自我发展能力将得到加强。</p><p>  每千度电价，从七十九元提高到一百一十五元。提价后，电力行业的资金利润率可达到百分之十左右。</p><p>  铁路客运价格提高一倍。货运价提高百分之五十。民航、轮船和汽车的客货运价格按合理比价相应提高。平信邮费从八分提到二角，其他邮电资费也相应提高。</p><p>  国有林区木材，每立方米出厂价从一百四十三元提高到三百五十元；同时，取消计划内外两种价格。</p><p>  3. 有步骤地提高农产品的价格水平，并使农产品内部比价逐步趋于合理。</p><p>  每五十公斤粮食的合同定购价，籼稻从十七元二角提高到三十五元，粳稻从二十二元四角提高到四十六元。小麦，从二十三元二角提高到三十九元。玉米，从十六元提高到二十八元。</p><p>  每五十公斤棉花的价格，从一百七十六元提到三百元，棉粮比价保持在一比七点五左右。</p><p>  生猪价格，内地每百斤提高到一百八十元，沿海和大城市郊区提高到二百元以上，猪粮比价保持在一比六左右。</p><p>  4. 消费品价格逐步实行市场调节，并在价格总水平上涨过程中，使内部比价同生产结构和消费结构大体协调。除城市口粮等个别品种外，基本上解决购销价格倒挂的问题，减少国家的补贴。</p><p>  高档消费品价格放开，同时实行高税收政策。这类商品包括：彩色电视机、电冰箱、纯毛呢绒和高档烟酒等。</p><p>  广大群众日用消费品的价格，上涨幅度要加以控制。其中，供求趋向缓和、成本降低潜力较大的产品，例如自行车、手表、缝纫机、电风扇和化纤产品等，相对价格要有所下降。</p><p>  城市食品价格，要按照有利于形成合理的消费结构和逐步减少补贴的原则进行改革。口粮价格有两种设想，一是提高销价，取消倒挂；二是销价提高一些，倒挂保留一些。可以看二、三年再决策。要逐步扩大猪肉和禽蛋的差价，引导消费多转向禽蛋。</p><p>  民用煤、煤气、自来水、市内交通等价格偏低，要适当提高。</p><p>  房租收费，按住房改革方案进行改革。</p><p>  结合工农业产品价格的改革，大力整顿流通环节，扭转流通领域与生产领域利益分配不合理的局面。</p><p>  实现上述改革目标，双轨制价格的混乱现象可以得到基本上解决，工农业之间以及它们各自内部的产品比价关系将朝着合理方向前进一大步；由市场形成价格的商品总额，在社会商品销售总额中所占的比重，将由现在的百分之五十左右提高到百分之七十至百分之八十左右。</p><p>  进行以上改革，五年内全国零售物价总水平大约上升百分之七十左右，其中城市上升百分之八十左右，农村上升百分之六十左右；职工生活费指数上升百分之九十左右。</p><p>  关于价格改革的实施步骤，总的想法是，重点突破，分步推进。前三、四年步子大一点，把主要措施推出台，物价总水平的上升幅度也相对地高一些。然后进行巩固完善，把物价总水平的上升幅度逐步降低下来。具体出台步骤的设想是：第一步，放开钢材价格，提高客票价格，农产品价格调整迈出一步；第二步，调整原油价格，农产品价格调整的步子走大一点；第三步，提高煤、电、货运价格，逐年放开一些加工工业产品价格。</p><h3 id="二-关于工资改革。" tabindex="-1">（二）关于工资改革。 <a class="header-anchor" href="#二-关于工资改革。" aria-label="Permalink to &quot;（二）关于工资改革。&quot;">​</a></h3><p>  五年工资改革总的要求是，在价格改革过程中，通过调整工资和适当增加补贴，保证大多数职工实际生活水平不降低，并能随着生产的发展有所改善；进一步贯彻按劳分配原则，克服平均主义；适当解决工资分配中一些突出不合理的问题，特别是脑体收入倒挂问题；调节社会收入分配，取缔非法牟取暴利行为，解决分配不公的矛盾；健全工资基金的宏观调控机制。具体要求是：</p><p>  1. 对职工继续实行若干生活必需品涨价后给予适当补贴的制度，对离退休人员也建立相应的补贴制度，并健全对低收入职工的生活补助制度。</p><p>  2. 全面推行和进一步完善企业工资与经济效益挂钩的办法，使职工工资增长主要依靠本企业提高劳动生产率和提高经济效益，基本实现企业工资与机关事业单位工资脱钩。在企业内部积极推行计件工资制和定额工资制。对企业的工资标准，采取调放结合的方针。一方面，随着生产的发展和物价指数的上升，逐步提高参考工资标准的水平；一方面，加大工资标准的弹性幅度，增加地区和产业工资标准的适用种类，企业内部的分配形式和办法由企业自主确定。</p><p>  3. 逐步建立与国家公务员制度相适应的行政机关工资制度，建立符合各自特点的科学教育文化卫生体育系统的工资制度，建立机关、事业单位工作人员正常升级、增加工资的制度。通过多增加一些脑力劳动者工资，以及放宽政策鼓励事业单位专业技术人员积极开展咨询服务活动增加收入等办法，逐步改变脑体收入倒挂的现象。</p><p>  4. 逐步健全对工资和个人收入的宏观调控体系，进一步加强银行、税务、审计、物价、统计等部门的监督管理职能，合理控制工资总额增长，建立个人收入申报制度，对高收入者严格征收收入调节税。</p><p>  5. 统盘考虑职工养老、待业、医疗等项保险，建立由国家、企业、个人合理负担的社会保险制度，并实行社会化管理。同时，减少各种津贴、补贴在职工个人收入中的比重，改善职工个人收入的结构，增加收入分配的透明度。</p><p>  实行以上改革，五年内职工平均货币工资将增长一倍左右，扣除生活费指数上升因素，平均实际工资每年增长百分之一到百分之二。脑力劳动者平均工资水平，将由现在低于一般体力劳动者平均工资的状况，转为高于一般体力劳动者。</p><p>  需要着重说明的是，由于对今后五年经济生活中许多复杂多变的因素还看不准，上述价格、工资改革的轮廓设想还很粗略。无论是放调价格的范围、幅度和实施步骤，还是工资改革的目标和要求，都需要进一步进行认真的研究和测算，并在实践中根据条件和情况的变化加以补充和修正。总的来说，我们还只能在坚持改革方向和有一个大体设想的前提下，走一步看一步，边探索边前进。</p><h2 id="四、一九八九年价格、工资改革的初步方案" tabindex="-1">四、一九八九年价格、工资改革的初步方案 <a class="header-anchor" href="#四、一九八九年价格、工资改革的初步方案" aria-label="Permalink to &quot;四、一九八九年价格、工资改革的初步方案&quot;">​</a></h2><p>  明年是价格、工资改革新起步的一年，这一步迈得好不好，至关重要。安排明年改革方案，考虑的基本原则是：在保持国民经济以适当速度持续增长的情况下，既要在理顺价格方面迈出重要一步，又要做到社会震动不过大，力争全国零售物价上涨幅度不高于今年，同时使明年跨出的一步能够为后几年改革创造条件。改革的具体设想和初步综合平衡的情况如下：</p><h3 id="一-价格改革的方案。" tabindex="-1">（一）价格改革的方案。 <a class="header-anchor" href="#一-价格改革的方案。" aria-label="Permalink to &quot;（一）价格改革的方案。&quot;">​</a></h3><p>  明年的改革，主要是：放开钢材价格，提高客运价格，农产品价格的调整迈出一步，并调整其他少数亟须解决的不合理价格。钢材价格混乱对生产资料市场的影响甚大。从改革钢材价格入手，有利于解决生产资料价格双轨制问题，改变流通领域的混乱现象，促进生产资料市场的发展；有利于压缩投资规模，控制社会总需求，改善宏观环境。当然，钢材价格放开，对使用统配钢材比重大的重点生产企业、重点建设工程和少数大城市影响较大。控制不好，也会推动物价的轮番上涨。</p><p>  在方案测算的过程中，也曾经考虑过，更大幅度地提高农产品特别是粮食的价格。这样做，对调动农民的生产积极性，促进农业持续增长，巩固整个国民经济发展的基础，无疑具有重要作用。问题是，农产品价格的大幅度上升，对城镇人民生活影响较大，国家财政难以承受。经过反复考虑，还是选择了先放钢材价格、同时适当调整农产品价格的方案。</p><p>  1. 放开钢材价格。根据不同钢材品种的供求状况，实行三种不同办法：小型型钢、线材、焊接管、热轧矽钢片和金属制品等五种钢材，产量约为二千二百万吨，占钢材总产量的百分之四十七，国内产需大体平衡，价格放开，全部实行市场调节。重轨、轻轨、轮网钢、一般型材、中厚板、无缝管等钢材品种，产需矛盾不大，但专用性强，为保证重点，避免产需脱节，采取放开价格，由国家优先订货、收购一部分、或帮助产需见面、协商定价的办法。这部分钢材的产量约为二千三百万吨，占总产量的百分之四十八。少数特别紧缺的钢材品种，实行调整价格、计划分配，这包括冷轧薄板、镀锡板、镀锌板、不锈板、不锈型钢、冷轧变压器矽钢片等钢材，国内产量二百多万吨，只占总产量的百分之五，但供需矛盾突出，每年需进口四百万吨左右。对于这部分紧缺钢材，价格要按优惠的原则及时调整，但近期不能放开。</p><p>  据冶金部和物资部提供的材料，以及国家体改委最近对八十个企业的典型调查，企业所用的钢材大约一半稍多一点是由计划分配的，约有百分之四十以上是从市场上采购的。统配钢材的国家定价每吨为七百元。物资部的统计材料，今年一至五月，用户的实际到厂价平均每吨一千一百多元，市场供应的钢材价格每吨约一千八百元，高于国家统配钢材的实际到厂价约七百元。冶金部提供的钢材出厂价价差也是七百元左右。国家体改委最近的典型调查，今年上半年计划分配的钢材和市场供应的钢材价格都在大幅度上涨，计划分配的钢材实际到厂价每吨为一千四百七十六元，从市场购进的钢材价格每吨为二千五百四十元，两种价格的水平和它们之间的差价，都高于冶金部、物资部提供的统计材料。考虑到近来钢材价格的较大幅度上涨带有某些不正常的因素，因此，我们在测算时仍采取了冶金部、物资部提供的综合材料。这样，钢材价格放开后，涨价总金额为一百七十六亿元左右。钢材价格放开后，相应调整铁矿石、生铁、钢坯等价格。以钢材为主要原料的机电产品价格同时放开，预计可能涨价三十四亿元。</p><p>  2. 提高陆、水、空运的客票价格。铁路客票价提高一倍，人公里从二分提到四分；行李、包裹运价和站台票价格适当提高。民航客票价提高百分之七十七，公路客票价提高百分之二十，水运客票价提高百分之八十。货运价格基本不动，只对矛盾特别突出的价格进行局部调整。客货运提价金额合计九十六亿元。</p><p>  3. 农产品价格改革迈出一步。</p><p>  粮食合同定购和公粮合计一千亿斤不变。对城镇居民定量供应的粮食、食油价格一律不动。</p><p>  合同定购的粮食，在稻谷每五十公斤提价不超过五元三角、小麦每五十公斤提价不超过一元五角、玉米每五十公斤提价不超过一元的限度内，按提价款由中央和地方分担的现行办法，调出省外部分相应提高调拨价的原则，由各地具体安排。预计合同定购粮食提价总额约四十亿元。</p><p>  粮食议转平的收购任务取消，改为随行就市收购。中央财政补贴的每斤六分四厘仍留给地方。地方必须收购的粮食，价差由地方财政补贴，谁用粮谁出钱。</p><p>  以上国家合同定购和议价收购的粮价总水平每五十公斤提高四元三角六分，提高幅度为百分之十八点七。</p><p>  是否取消三挂钩，将价差款转为粮食收购的价外补贴，由各地根据自已的情况，在不影响棉花等经济作物和生猪价格上涨的条件下，自行决策。</p><p>  逐年压缩城镇口粮以外的行业平价粮食的销售。争取在两三年内，将行业用粮价格全部放开。放开的原则是：先农村，后城市；先中小城市，后大城市；先与群众生活影响较小的行业，后其它部分。农村水库移民、救灾用粮可暂不变动，或采取补差价的办法。行业用粮价格放开后，原来议转平的差价仍留给各地，主要用以解决影响职工生活的暗补改明补，以及充实粮食丰歉的调节基金，不得移作他用。在这些原则下，哪些先放，哪些后放，什么时候放，由各省、自治区、直辖市分别决定，报国务院备案。明年全国大体按二百亿斤左右掌握。</p><p>  合同订购的油料中，花生、油菜籽适当提价，提价额五亿七千万元。加上议价油料价格上涨，油料提价总金额约十五亿元。</p><p>  棉花收购价格不动，明年看一年。国家定价的其它经济作物，价格也不提高。</p><p>  4. 调整少数急待调整的不合理价格，合计一百零七亿元。其中包括：平信邮资从八分提到二角，计五亿八千万元；每斤食盐零售价提高八分，盐及盐化工产品提价三十五亿元；报纸提价十八亿元；糖及糖制品提价三十亿元；尿素每吨从四百一十元提到五百元，提价总额八亿三千万元；北方国营林区木材提价十亿元。</p><p>  5. 人民币对美元的汇价，由三元七角调到四元二角，增加五角；二十八种进口补贴商品除粮食、化肥外，改为代理价；并考虑到国际市场价格上涨的因素，预计将推动市场物价上涨二百一十四亿元。国际市场商品价格剧烈变动时，进口关税税率应适当调整，以减少国际市场价格对国内价格的冲击。</p><p>  按照以上设想，明年物价变动的概况是：主要生产资料涨价四百三十四亿元；农产品收购涨价二百九十六亿元；消费品零售价格上涨九百四十六亿元，主要农业生产资料零售价提高二十一亿元。</p><p>  这样全国零售物价总水平上升百分之十五左右，其中城市百分之十七，农村百分之十二。职工生活费指数上升百分之十九。在全国零售物价上升的百分之十五中，由于出台价格改革措施包括汇率调整推动价格上涨约百分之七点五，已经放开的商品价格自发涨价约百分之四，今年涨价对明年翘尾巴影响约百分之二点四，进口商品的国际市场涨价的影响零点五。贷款利率再提高百分之二，将推动零售物价总水平上升近百分之一。</p><h3 id="二-提价利益的分配。" tabindex="-1">（二）提价利益的分配。 <a class="header-anchor" href="#二-提价利益的分配。" aria-label="Permalink to &quot;（二）提价利益的分配。&quot;">​</a></h3><p>  把涨价增加的收入基本上拿到国家手中，增加财政收入，减轻财政负担；对企业采取从紧的原则，以促使企业挖掘潜力，提高经济效益。</p><p>  1. 钢材涨价的收入一百七十六亿元，矿石、钢坯等上游产品提价约占用四十八亿元，职工工资和其它材料、费用增加四十二亿元，扣除这两个因素所引起的成本上升九十亿元后，钢厂约增加收入八十六亿元。对这部分涨价收入，国家财政按现行规定征税，将得到五十八亿元，其余二十八亿元，通过开征专项收入把二十五亿元收回来。</p><p>  2. 铁路客运提价的收入六十二亿元，扣除钢材涨价和增加费用等影响生产维修成本上升约二十二亿五千万元，财政征收营业税三亿元，所余三十七亿元，拟通过开征专项收入拿回三十亿元。</p><p>  3. 银行调整利率净增加的利息收入，全部上交财政。</p><p>  4. 已确定的财政包干体制不变价格、工资改革中的开支，按现行体制由中央和地方分级负担。中央对地方财政既不挤也不让，个别突出不合理的问题个别解决。各地应努力通过增收节支解决自己的财政问题，发不出工资的可以减人。</p><h3 id="三-职工工资的安排。" tabindex="-1">（三）职工工资的安排。 <a class="header-anchor" href="#三-职工工资的安排。" aria-label="Permalink to &quot;（三）职工工资的安排。&quot;">​</a></h3><p>  考虑到明年价格改革中，有些措施对职工的实际生活影响较小，例如提高客票、邮资、报纸价格等主要影响集团消费，因此，明年职工平均工资按增长百分之十五考虑。按此计算，需增加职工工资总额四百零八亿元（含增人因素，下同），其中全民所有制单位为三百一十二亿元。职工平均货币工资，由今年的一千六百九十九元提高到一千九百五十四元，增加二百五十五元。其中，全民所有制单位由今年的一千八百元提高到二千零七十元，增加二百七十元。</p><p>  在全民所有制职工增加的三百一十二亿元工资总额中，机关事业单位计划安排一百零七亿元，平均货币工资预计增长百分之十九点三；企业单位计划安排二百零五亿元，平均货币工资预计增长百分之十三点四。</p><p>  机关事业单位明年出台的工资改革措施有：</p><p>  调整工资标准。机关、事业单位工作人员普遍调升一级工资，同时去掉现行工资标准各职务的最低档，并适当延伸等级，增加高档。这样。大约人均每月增加工资八元，全国全年约增加工资二十六亿六千万元。</p><p>  发放物价补贴。仍按特定基本消费品定量价格补贴办法，每人每月增加补贴五元，半年需要八亿三千万元。这项措施可先打入财政预算，暂不宣布，具体实施办法待明年上半年视物价变动情况再确定。</p><p>  适当解决工资关系中的突出问题。主要是：提高教授、讲师、助教（含科学、卫生等系统相当职务的专业技术人员）的工资水平，提高大中专毕业生的定级工资水平，提高教龄、护龄津贴标准，以及解决其它一些突出问题。这些，全国需三十一亿三千万元。</p><p>  机关、事业单位职工的奖金不到两个月工资的增发到两个月，全年需要八亿三千万元。</p><p>  以上几项，增加工资总额七十四亿元，平均每人每月增加二十二元。</p><p>  全民所有制企业单位明年增加工资的措施是：</p><p>  通过提高经济效益增加工资。初步测算，企业职工平均货币工资可随效益提高增长百分之五左右，相当于平均每人每月增加七元五角，全国共计六十五亿元。这部分资金原则上由企业自主安排使用，可以允许企业从中拿出一部分用于调整工资标准。</p><p>  从明年下半年起，每人每月发放价格补贴五元（暂不宣布），共计二十二亿元。</p><p>  考虑到价格改革的影响和企业承受能力不同的情况，拟适当安排一些工资调剂基金，按人均每月五元计算，由地区、部门掌握，不平均发放，根据企业在价格变动中受损受益的情况调整其挂钩的工资基数。全年需四十三亿元。</p><p>  三项合计，加上其它增加工资措施，总计一百四十五亿元，平均每人每月增加十七元。</p><p>  从明年一月起，对全国离退休人员二千一百五十二万人每人每月增加离退休费八元，从下半年开始，再发给每人每月五元的物价补贴（暂不宣布）。全年共计二十七亿元。</p><h3 id="四-调价对农民收入和支出的影响。" tabindex="-1">（四）调价对农民收入和支出的影响。 <a class="header-anchor" href="#四-调价对农民收入和支出的影响。" aria-label="Permalink to &quot;（四）调价对农民收入和支出的影响。&quot;">​</a></h3><p>  初步测算，由于提高粮食等农产品收购价格，以及由此而引起的其它农产品涨价，明年农民将增加收入约二百九十六亿元。由于消费品和农业生产资料调价，农民需要增加支出二百六十一亿元。从这两方面算帐，农民增收节支基本持平。随着明年农业生产的发展，农民收入将进一步增加。对化肥、薄膜等农民急需的农用生产资料，实行专营，稳定价格，取缔中间盘剥，以保证农民增产增收。</p><h3 id="五-价格、工资改革对基本建设的影响。" tabindex="-1">（五）价格、工资改革对基本建设的影响。 <a class="header-anchor" href="#五-价格、工资改革对基本建设的影响。" aria-label="Permalink to &quot;（五）价格、工资改革对基本建设的影响。&quot;">​</a></h3><p>  根据上述价格、工资改革设想测算，明年全民所有制单位基本建设工程造价将上涨百分之十五，涨价金额一百七十亿元。其中，使用统配物资的中央投资涨价百分之二十一，涨价金额一百二十亿元。为了压缩基本建设投资规模，除明年新增加的能源、交通基金仍用于增加基本建设基金，弥补小部分贬值以外，重点建设贬值的其余部分，要通过自行消化、转给地方、采用贴息调整信贷结构和停缓建一些项目来解决。一般工程造价的上升，全部自行解决。这样做将有一批在建项目停下来，许多新项目不能开工。一批利用外资和引进项目将延长工期，不能按合同规定执行，涉外处理难度较大。</p><h3 id="六-财政收支平衡情况。" tabindex="-1">（六）财政收支平衡情况。 <a class="header-anchor" href="#六-财政收支平衡情况。" aria-label="Permalink to &quot;（六）财政收支平衡情况。&quot;">​</a></h3><p>  1. 初步测算，由于提高生产资料和客运价格，财政增收四十二亿元；由于提高农产品价格，财政增支五十九亿元。收支相抵支大于收十七亿元。</p><p>  2. 由于增加工资和补贴，财政增支减收二百零七亿元。</p><p>  3. 调整利率、汇率。财政减收二十亿元。</p><p>  以上三项，将扩大财政收支差额二百四十四亿元。</p><p>  4. 据财政部初步测算，明年农业生产增长百分之四，工业生产增长百分之十，国民生产总值增长百分之八，国内财政收入可能达到二千五百九十亿元；各项支出从紧安排，总支出为二千七百五十亿元。差额为一百六十亿元。加上调价和增加工资后发生的收支差额，明年财政支大于收四百零四亿元。</p><p>  现在想到的增收节支措施是：</p><p>  ——对彩电、冰箱、小轿车征收特别调节税，增加收入五十亿元；国家专营一部分彩电，增加收入七十八亿元（所需六亿美元外汇尚待落实）。</p><p>  ——整顿和强化税收征管工作，包括加强农林特产税和乡镇企业税的征管，增加收入二十三亿元。农林特产税和乡镇企业税的收入留给地方，作为提高粮价和支援粮食生产的资金来源。</p><p>  ——借新债还旧债四十五亿元。</p><p>  ——向国外发行政府债券或借低息贷款八亿美元，用以偿还到期的外债本息三十二亿元。</p><p>  ——建立养老保险信托基金，发行特种长期债券十五亿元。</p><p>  ——压缩中央对地方的专项拨款十亿元。</p><p>  ——动用一百一十二专项基金二十亿元。</p><p>  采取这些措施后，财政可增收减支二百二十三亿元，还有差额一百八十一亿元。</p><p>  明年价格、工资改革方案存在的主要问题是，百分之十五的物价指数和百分之十九的职工生活费指数可能打不住，职工的补偿特别是机关事业单位职工和部队的补偿可能不够；重点建设受到材料涨价、汇率变化和提高贷款利率三重影响，投资贬值较多，明年一年还可以，连续几年可能问题较大；现有固定资产没有进行重新估价，没有考虑折旧费贬值的因素，长此下去会发生吃老本的问题；提了粮食价，棉花价未动，将对棉花生产发生不利影响。此外，住房改革要求增加工资的部分，打得也不够。财政还有差额一百八十多亿元有待于解决。但是，现在看，恐怕也只能这样考虑。有些问题可以作进一步研究。</p><h2 id="五、主要风险和基本对策" tabindex="-1">五、主要风险和基本对策 <a class="header-anchor" href="#五、主要风险和基本对策" aria-label="Permalink to &quot;五、主要风险和基本对策&quot;">​</a></h2><p>  在国务院常务会议和物价委员会讨论上述方案的过程中，大家普遍认为在目前条件下这个方案是一个积极稳妥、比较可行的方案，但在实施中困难不少，也有相当的风险，主要的问题是如何控制通货膨胀。</p><p>  近几年来，我国通货膨胀率逐渐转高，今年物价指数将上升百分之十五左右；市场货币流通量连续几年偏多，今年货币增发量又将超过四百亿元，比去年增长百分之三十以上。内外债还本付息即将进入高峰，据财政部测算，今年还本付息总额为九十五亿元，明年为一百三十五亿元，一九九○年将猛增到四百二十八亿元，一九九二年将达到四百九十亿元，这几年是财政的很大难关。我国主要进口商品钢材、有色金属、粮食、化肥等，国际市场价格大幅度上涨，今年六月的国际市场离岸价多数比去年上涨百分之五十到一倍，这将造成外汇平衡困难，进口数量减少，影响国内生产建设的发展。农业生产特别是粮食生产不稳定，今年的粮食可能会有较多的减产。在这样的环境下进行价格、工资改革，必须毫不动摇地坚持边积极推进改革、边综合治理通货膨胀的方针。如果不这样做，必然会带来各种商品价格轮番上涨，工资和物价竞相推进，不仅达不到理顺价格关系、形成价格合理机制的目的，而且会在更高的物价水平上造成价格关系的新扭曲，整个经济生活就会陷入严重混乱。</p><p>  统观全局，国务院常务会议认为，必须根据“抑速度，压规模；紧信贷，控消费；开财源，减赤字；顾大局，守纪律”的方针，采取以下的基本对策。</p><p>  1. 继续坚持长期稳定发展经济的战略。我国经济的发展需要有必要的速度，以切实增加有效供给，但这种速度必须以提高经济效益为前提，决不能靠过多地占用银行贷款和过多地消耗能源原材料，追求脱离实际可能的过高速度。建议明年计划确定工业增长百分之十，农业增长百分之四，国民生产总值增长百分之八。各个综合经济管理部门都要以此作为宏观调控的主要目标，决不能认为速度越高越好，不能在速度上助长攀比之风，不能把产值增长速度的高低作为评价工作好坏的主要标准。</p><p>  2. 严格控制货币发行和信贷规模。今年的货币增发量，要控制在四百亿元左右，明年大体维持这个水平。今后的货币供应增发率，要力争逐步做到相当于经济增长率和结构性物价上涨幅度之和。这要作为经济工作的一项重要原则确定下来。在适当紧缩信贷总规模的同时，要在合理调整信贷结构上下大功夫，该保的要保，该压的要压，决不能把硬缺口留在外面，结果又导致信贷总规模的膨胀。</p><p>  3. 坚决控制建设规模，大力调整投资结构。明年的基本建设投资总规模，维持今年的水平。由于物价上涨引起的投资贬值，除重点建设用增长的能源交通基金弥补一部分外，对其它建设，一律不予补偿。银行用于固定资产投资的贷款总额，明年不得增加。要按照国家产业政策的要求，采取发行股票、债券和实行差别利率等经济手段，以及必要的行政手段和法律手段，坚决压缩楼堂馆所等非生产性建设、一般性加工工业建设和不必要的重复建设，把有限资金用到社会急需的、能够增强经济发展后劲的重点建设上来。</p><p>  4. 坚决有效地控制消费基金的过快增长。消费需求增长超过生产增长和劳动生产率提高幅度的现象，是造成通货膨胀的重要根源，必须引起我们的严重关注。在进行价格、工资改革的过程中，如果不严格控制消费增长，继续失控，后果不堪设想。我们要努力做到绝大部分居民生活不致由于价格改革而下降，但也不能排除某些时候一部分人生活水平有所下降，这一点要向广大干部和群众讲清楚，自觉抑制过高的消费欲望。职工收入的增长一定要低于劳动生产率的提高，农民收入的增加一定要主要依靠发展生产。要下决心压缩集团购买力，压缩行政经费。对工资、奖金、津贴、福利费用和行政费用等项开支，银行、财政、审计、监察、统计等部门必须切实负起责任来，严格检查监督。</p><p>  5. 必须努力保持财政收支的基本平衡。千方百计开源节流，深入开展增产节约、增收节支运动。今年的财政赤字，要保证比原定计划八十亿元有所减少。明年的财政赤字，要力争维持今年的水平，不再增加。明年除了国防费和科技教育事业费之外，其它方面的开支都基本上维持今年的水平，有多少钱办多少事，没有钱就停办缓办。</p><p>  6. 坚持外汇收支平衡，严格控制外债额度。目前，全国外汇结存虽然有所增加，但中央的外汇仍然吃紧。明年在保持外贸外汇包干体制不变的前提下，必须把中央进口的部分物资转由地方进口，地方要相应地调整外汇使用方向和进口商品结构。现在有些地方敞开口子借外债，利用外资兴办企业不考虑国内资金配套能力，这是造成信贷失控、通货膨胀的一个不可忽视的因素。因此，必须采取有效措施加强对外债的统一管理，并迅速建立偿还外债的基金制度，以应付即将到来的还债高峰。</p><p>  上述对策的基本精神仍然是深化改革、稳定经济。我们必须把认识统一起来，边进行价格、工资改革，边综合治理通货膨胀，使改革方案得以顺利出台并取得预期效果。如果不是这样，改革措施或者难以顺利出台，或者会受到较大挫折。出现了这种局面，党和政府的威信和改革的声誉，将受到严重损伤。还应该看到，坚持按上述的要求办事，必然有一批亏损企业和效益差的企业破产，一批在建的项目包括合资项目要停建缓建，失业人员会有较多的增加。对此，各级政府在思想上、组织上、制度上和措施上应提前做好必要的准备，以免措手不及。</p><p>  大家在讨论中普遍认为，为了保证改革的顺利进行，必须加强党的领导。全党同志特别是各级领导干部都要顾大局，守纪律，振奋精神，恪尽职守。兢兢业业，团结群众，共度难关。目前相当普遍存在着的有令不行、有禁不止的状况，必须迅速地切实地加以扭转。党的领导是否加强，从经济领域来说，当前主要就看上述基本方针和对策能否得到真正的贯彻落实。</p><h2 id="六、必须采取的配套措施" tabindex="-1">六、必须采取的配套措施 <a class="header-anchor" href="#六、必须采取的配套措施" aria-label="Permalink to &quot;六、必须采取的配套措施&quot;">​</a></h2><p>  上面讲到的基本对策，不仅需要全党认识上的统一，还必须有切实有效的具体措施，才能真正落实。价格、工资改革的推进，也必须有各个方面的配套改革相适应。在酝酿和讨论价格、工资改革方案的过程中，各有关部委已经提出了若干配套措施，主要有以下的几个方面。</p><p>  第一，加强各级银行特别是中央银行的调控职能，强化货币发行约束，千方百计稳定金融。</p><p>  适应居民和企业保值心理，逐步提高存款利率，开设多种形式的有奖储蓄，稳定和扩大储蓄存款。</p><p>  按产业政策调整信贷结构。下决心关、停、并、转一批亏损企业和效益很差的企业，坚决停、缓建一批楼堂馆所和不必要的重复建设项目。</p><p>  适当提高准备金率，以利于控制专业银行贷款规模。</p><p>  改革企业流动资金贷款办法。根据产业政策和企业的资信条件，对不同企业实行不同的流动资金贷款利率。企业新增流动资金，应当主要依靠企业自有资金补充。由于涨价而引起的原有库存物资增值，要用于补充企业流动资金，不准挪作它用。对超储物资所占用的流动资金，不予贷款或实行高利率。</p><p>  积极发展债券、股票市场，大力开展各种保险事业，加强资金融通和吸收社会游资。</p><p>  第二，推进企业机制改革，强化企业管理，较大幅度地提高企业经济效益。</p><p>  坚持和完善企业经营承包制。对目前行之有效的竞争招标、风险抵押等经验，要积极加以推广。</p><p>  对那些供求大体平衡、生产工业消费品的企业，可以放开经营，进一步把它们推向自负盈亏的轨道。把亏损企业推向市场竞争，形成扭亏机制，减少企业亏损。</p><p>  在宏观适度紧缩和行政指导下，广泛推行企业的兼并和联合，改善企业组织结构。</p><p>  优化企业劳动组合，严格按劳动量、工作量进行定额定员，加强培训，严格考核，严肃纪律，提高职工素质，扭转纪律松弛、效率低下的现象。对多余人员实行留职离岗、厂内待业等多种办法消化。</p><p>  调整就业政策，引入竞争机制，允许一定比例的失业率。与此相适应，尽快建立新的社会保障制度。明年全民所有制单位自然减员的二百五十万人，由职工队伍内部调剂解决，不再向社会招工。现有的一千多万计划外用工，要进行清理和压缩。</p><p>  第三，加强市场的组织和建设。</p><p>  整顿、清理流通环节，坚决取消不必要的各种公司。除极少数经特别批准的公司可以兼有行政管理和企业经营两种职能外，所有公司必须实行政企分开。大宗的生产资料交易，要坚持和发展产需直接见面的合同制。</p><p>  制定市场交易规则和管理制度，建立正常的市场秩序。重要生产资料放开后，要实行公开销售，严禁黑市交易，严禁封锁资源、垄断价格、倒买倒卖、囤积居奇、哄抬物价、行贿受贿等非法行为和不正当竞争手段。</p><p>  国家要加强对市场的组织领导和宏观调控。及时分析市场动态，加强信息指导，及时采取经济手段和行政措施调节市场变动趋向。为此，要建立必要的生产资料市场调控基金，包括一定的物资、财力和外汇。</p><p>  明年放开钢材价格，必须先做好市场组织的准备工作，准备好再出台。对已经签订的定点定量合同，除价格可以重新协商外，应继续保证执行，不得随意中断。国家优先定购的钢材，生产企业要优先保证签订和履行合同。对按合理工期施工的重点工程项目所需的钢材，尽量由物资部门实行配套承包供应，保证工期，如期建成投产。</p><p>  第四，采取特殊措施，渡过财政难关。</p><p>  适应价格改革的新形势，开征一些新税种，强化税收征管工作，把应该拿回来的涨价好处拿回来，把应该收的税尽可能都收上来。税权不能分散，不能乱开减免税收的口子，已经减免的要进行认真清理。税务系统应实行双重领导，以垂直领导为主。</p><p>  已实行的地方财政包干体制不变。对亏损县、亏损企业，要动点手术，不能一有困难就给补贴。县一级的五套机构人员太多，养不起，要改革。</p><p>  今后五年通过出卖一部分国有资产，筹集一笔资金。一是选择一批盈利的大中型国营企业发行股票。股票收入或上交国家财政，或留给地方和企业抵作投资资金。二是变卖一部分国营小企业，包括小型国营工业企业和小型农牧企业、商业企业。三是在沿海部分城镇和集市出租或转让一些国有土地使用权。四是卖一部分城镇住房。全国城镇现有公有住房二十一亿平方米，可以出售的约十亿平方米。按每平方米建筑面积平均售价一百五十元估算，共可收回一千五百亿元，可以考虑分五年卖出。为了偿还到期的国家债务，不论地方或企业出售的公用住房，大约一半收入上交国家财政，一半作为地方和企业的建房基金。出售一部分公产，不仅是解决财政困难的重要办法，也是推进和深化改革的重大措施。应当在认真调查研究的基础上，提出系统的办法、政策和措施，并制定相应的法令法规，使之真正落实。</p><p>  现在提出的配套措施还很不够，有的还不具体，有的可能尚未想到。各有关部门必须进一步解放思想，开阔思路，继续抓紧研究。</p><p>  国务院常务会议认为，从现在起就要紧急行动起来，从两个方面为明年价格、工资改革的出台做好准备。一是改革方案的继续研究和完善；二是积极治理经济环境和经济秩序。有的配套改革措施，研究好了就可以提前出台，不必都等到明年。今年后四个月要切实抓好控制货币发行、减少财政赤字、进一步紧缩楼堂馆所等非生产性建设，坚决清理和整顿公司和开展财务税收大检查等项工作。对目前已经出现的有些单位抢购和囤积钢材，滥发奖金和补贴，以及在外汇的结算和支付上做手脚等现象，必须采取坚决措施加以纠正，严肃政纪法纪。各级政府和各部门，必须加强责任心，各司其职，同心协力，转变工作作风，提高工作效率，保证价格、工资改革和各项配套改革的顺利进行。</p>',153)])])}const f=a(l,[["render",i]]);export{u as __pageData,f as default};
